import { useContext } from 'react';

import { TreeMapStateContext } from './store.js';
import { useStoreSelector } from '../../../core/store/selector.js';
import { TreeMapState } from '../types/state.js';

export const useSelector = <T>(selector: (state: TreeMapState) => T): T =>
  useStoreSelector<T, TreeMapState>(TreeMapStateContext, selector);

export const useSetState = (): typeof setState => {
  const { setState } = useContext(TreeMapStateContext);

  return setState;
};

export const useTreeMapState = (): TreeMapState =>
  useSelector((state: TreeMapState) => state);

export const useHighlightedState = (): TreeMapState['highlightedItems'] =>
  useSelector((state: TreeMapState) => state.highlightedItems);

export const useTooltipState = (): TreeMapState['tooltip'] =>
  useSelector((state: TreeMapState) => state.tooltip);

export const useTooltipPinnedState = (): TreeMapState['tooltip']['pinned'] =>
  useSelector((state: TreeMapState) => state.tooltip.pinned);

export const useTooltipVisibleState = (): TreeMapState['tooltip']['visible'] =>
  useSelector((state: TreeMapState) => state.tooltip.visible);

export const useGroupsSelectedState = (): TreeMapState['groupsSelected'] =>
  useSelector((state: TreeMapState) => state.groupsSelected);

export const useVisibleNodesState = (): TreeMapState['visibleNodes'] =>
  useSelector((state: TreeMapState) => state.visibleNodes);

export const useOverlayState = () =>
  useSelector((state: TreeMapState) => state.overlay);
